#!/usr/bin/env node
/**
 * Vendor the eks-agent-platform CRD schemas this repo validates `platform.yaml`
 * against, and keep the vendored copies honest about where they came from.
 *
 * The CRDs are generated by controller-gen in nanohype/eks-agent-platform under
 * `operators/config/crd/bases/`. `platform.yaml` is applied against exactly
 * those schemas, so the gate needs them — but resolving them over the network
 * at gate time makes the verdict depend on whatever upstream happens to be that
 * minute, and makes an outage look like a pass. So the copies are committed
 * here under `schemas/crd/`, and `schemas/crd/provenance.json` records the
 * upstream repository, the pinned commit, and a SHA-256 per file.
 *
 * That split gives the gate two independent properties, and this script owns
 * the second one:
 *
 *   1. Tamper detection — `scripts/validate-platform-manifests.mjs` verifies
 *      every digest in `provenance.json` before it reads a schema. Editing a
 *      vendored copy (widening an enum, dropping a `required`) fails the gate
 *      even though the file is still valid YAML. Offline, deterministic, runs
 *      on every job that touches the manifest.
 *
 *   2. Upstream drift detection — this script's `--check` mode reads the CRDs
 *      from nanohype/eks-agent-platform *at the pinned ref* and byte-compares
 *      them with the vendored copies. A hand-edited copy, a bumped `ref` that
 *      nobody re-vendored, or a digest that no longer describes the file all
 *      fail here. CI runs it, so a pin that has stopped describing reality
 *      surfaces as a red check rather than a schema quietly frozen in time.
 *
 * Usage:
 *   node scripts/sync-crd-schemas.mjs            # re-vendor + rewrite digests
 *   node scripts/sync-crd-schemas.mjs --check    # CI gate: exit 1 on drift
 *
 * Two source modes, both pinned:
 *   - $EKS_AGENT_PLATFORM_DIR points at a checkout. Under `--check` that
 *     checkout's HEAD must equal `provenance.ref` — a working tree at some
 *     other commit is not evidence about the pin, so it is refused rather than
 *     compared.
 *   - Otherwise the files are fetched from raw.githubusercontent.com at
 *     `provenance.ref`.
 *
 * Every failure is loud and fatal. An unreachable upstream, a missing file, a
 * malformed record, or a checkout at the wrong commit exits non-zero; no path
 * through this script reports success without having compared something.
 *
 * Re-vendoring (no `--check`) takes the ref from the checkout's HEAD when one
 * is given, so `git -C ../eks-agent-platform checkout <sha> && npm run
 * schemas:crd` is how the pin moves: one commit carrying the new ref, the new
 * digests, and the schema diff, reviewable together.
 */
import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const ROOT = join(SCRIPT_DIR, "..");
const SCHEMA_DIR = join(ROOT, "schemas", "crd");
const PROVENANCE = join(SCHEMA_DIR, "provenance.json");
const CHECK = process.argv.includes("--check");

const git = promisify(execFile);
const out = (line) => process.stdout.write(`${line}\n`);
const digest = (buf) => createHash("sha256").update(buf).digest("hex");

/** Abort with a reason. This script has no soft failure mode. */
function fail(message, remedy) {
  process.stderr.write(`\n  ✗ ${message}\n`);
  if (remedy) process.stderr.write(`    ${remedy}\n`);
  process.stderr.write("\n");
  process.exit(1);
}

/** Read and validate `schemas/crd/provenance.json`. */
async function readProvenance() {
  let raw;
  try {
    raw = await readFile(PROVENANCE, "utf8");
  } catch (error) {
    fail(
      `cannot read schemas/crd/provenance.json (${error.message})`,
      "The vendored CRD schemas and their provenance record travel together — restore both.",
    );
  }
  let record;
  try {
    record = JSON.parse(raw);
  } catch (error) {
    fail(`schemas/crd/provenance.json is not valid JSON: ${error.message}`);
  }
  for (const key of ["repository", "sourcePath", "ref", "files"]) {
    if (!record[key]) fail(`schemas/crd/provenance.json is missing \`${key}\``);
  }
  if (!/^[0-9a-f]{40}$/.test(record.ref)) {
    fail(
      `schemas/crd/provenance.json \`ref\` must be a full 40-character commit SHA, got \`${record.ref}\``,
      "Pinning a SHA rather than a branch is what makes the drift comparison mean anything.",
    );
  }
  if (!Array.isArray(record.files) || record.files.length === 0) {
    fail("schemas/crd/provenance.json `files` must be a non-empty array");
  }
  for (const entry of record.files) {
    if (!entry?.file) fail("schemas/crd/provenance.json has a `files` entry with no `file`");
    if (CHECK && !/^[0-9a-f]{64}$/.test(entry.sha256 ?? "")) {
      fail(
        `schemas/crd/provenance.json entry \`${entry.file}\` carries no valid sha256`,
        "Run `npm run schemas:crd` to re-record the digests.",
      );
    }
  }
  return record;
}

/** Read one CRD out of a local checkout of the operator repo. */
async function fromCheckout(checkout, record, file) {
  const path = join(checkout, record.sourcePath, file);
  try {
    return await readFile(path);
  } catch (error) {
    fail(
      `cannot read ${record.sourcePath}/${file} from $EKS_AGENT_PLATFORM_DIR: ${error.message}`,
      `Point EKS_AGENT_PLATFORM_DIR at a checkout of ${record.repository}.`,
    );
  }
}

/** Fetch one CRD from GitHub at the pinned ref. */
async function fromGithub(record, file) {
  const url = `https://raw.githubusercontent.com/${record.repository}/${record.ref}/${record.sourcePath}/${file}`;
  let response;
  try {
    response = await fetch(url);
  } catch (error) {
    fail(
      `cannot fetch ${url}: ${error.message}`,
      "The upstream comparison could not run. That is a failure, not a skip.",
    );
  }
  if (!response.ok) {
    fail(`cannot fetch ${url}: HTTP ${response.status} ${response.statusText}`);
  }
  return Buffer.from(await response.arrayBuffer());
}

/** The commit a checkout is sitting on, or null if it is not a git tree. */
async function headOf(checkout) {
  try {
    const { stdout } = await git("git", ["-C", checkout, "rev-parse", "HEAD"]);
    return stdout.trim();
  } catch {
    return null;
  }
}

async function main() {
  const record = await readProvenance();
  const checkout = process.env.EKS_AGENT_PLATFORM_DIR;
  const head = checkout ? await headOf(checkout) : null;

  if (checkout && CHECK) {
    // A working tree at some other commit says nothing about the pin, so it is
    // refused outright rather than producing a comparison that reads as
    // authoritative and isn't.
    if (head === null) {
      fail(
        `$EKS_AGENT_PLATFORM_DIR (${checkout}) is not a git checkout`,
        "The drift check compares against the pinned commit, so it needs one it can verify.",
      );
    }
    if (head !== record.ref) {
      fail(
        `$EKS_AGENT_PLATFORM_DIR is at ${head}, not the pinned ${record.ref}`,
        "Check the pinned commit out, or unset EKS_AGENT_PLATFORM_DIR to compare against GitHub.",
      );
    }
  }

  const origin = checkout
    ? `${checkout} @ ${head ?? "unknown"}`
    : `${record.repository}@${record.ref} (raw.githubusercontent.com)`;

  const problems = [];
  const vendored = [];

  for (const entry of record.files) {
    const upstream = checkout
      ? await fromCheckout(checkout, record, entry.file)
      : await fromGithub(record, entry.file);

    if (!upstream.toString("utf8").includes("kind: CustomResourceDefinition")) {
      fail(
        `${entry.file} from ${origin} is not a CustomResourceDefinition — refusing to vendor it`,
      );
    }

    const dest = join(SCHEMA_DIR, entry.file);

    if (CHECK) {
      const local = await readFile(dest).catch(() => null);
      if (local === null) {
        problems.push(`${entry.file} — the vendored copy is missing`);
        continue;
      }
      if (!local.equals(upstream)) {
        problems.push(`${entry.file} — the vendored copy differs from ${origin}`);
      }
      if (digest(local) !== entry.sha256) {
        problems.push(
          `${entry.file} — sha256 ${digest(local)} does not match the recorded ${entry.sha256}`,
        );
      }
      continue;
    }

    await writeFile(dest, upstream);
    vendored.push({ file: entry.file, sha256: digest(upstream) });
    out(`↻ schemas/crd/${entry.file}`);
  }

  if (CHECK) {
    if (problems.length > 0) {
      process.stderr.write(
        `\n  ✗ the vendored CRD schemas are not what ${origin} says they are:\n`,
      );
      for (const problem of problems) process.stderr.write(`      - ${problem}\n`);
      process.stderr.write(
        "\n    Run `npm run schemas:crd` to re-vendor and re-record the digests.\n" +
          "    Never hand-edit the copies — the gate reads them as the operator's own schema.\n\n",
      );
      process.exit(1);
    }
    out(`✓ ${record.files.length} vendored CRD schemas byte-identical to ${origin}, digests match`);
    return;
  }

  const { _README, ...rest } = record;
  await writeFile(
    PROVENANCE,
    `${JSON.stringify({ _README, ...rest, ref: head ?? record.ref, files: vendored }, null, 2)}\n`,
  );
  out(`✓ vendored ${vendored.length} CRD schemas from ${origin}`);
  out(`  provenance pinned to ${record.repository}@${head ?? record.ref}`);
}

main().catch((error) => {
  process.stderr.write(`sync-crd-schemas failed: ${error.stack ?? error.message}\n`);
  process.exit(1);
});
